<script setup>
import { Head, Link, router, usePage, usePoll } from '@inertiajs/vue3';
import { computed, ref, watch, onMounted, onBeforeUnmount } from 'vue';
import OrderProgress from '../../../Components/OrderProgress.vue';
import Dialog from '../../../Components/Shared/Dialog.vue';
import AppLayout from '../../../Layouts/AppLayout.vue';
import { paymentCountdown } from '../../../Support/paymentExpiry.js';
import { money } from '../../../Support/cart.js';
defineOptions({ layout: AppLayout });
const props = defineProps({ walkInUrl: String, periodName: String, period: Object, paymentDeadline: String, serverNow: String, orders: Object, backUrl: String, deliveryUrl: String, bulkStatusUrl: String, ordersUrl: String, view: String, viewCounts: Object, focused: Boolean, selectableOrders: { type: Array, default: () => [] } });
const clock = ref(Date.now());
let offset = Date.parse(props.serverNow) - Date.now();
let clockTimer;
watch(() => props.serverNow, value => { offset = Date.parse(value) - Date.now(); clock.value = Date.now(); });
onMounted(() => { clockTimer = setInterval(() => { clock.value = Date.now(); }, 1000); });
onBeforeUnmount(() => clearInterval(clockTimer));
const currentTime = computed(() => clock.value + offset);
const sessionClosed = computed(() => !props.period || ['closed', 'cancelled', 'ended'].includes(props.period.status) || currentTime.value >= Date.parse(props.period.closesAt));
const beforeOpening = computed(() => !sessionClosed.value && currentTime.value < Date.parse(props.period?.opensAt));
const sessionTime = computed(() => paymentCountdown(beforeOpening.value ? props.period?.opensAt : props.period?.closesAt, currentTime.value));
const deadlineTime = value => value ? new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '';
const views = [{ key: 'new', label: 'To process' }, { key: 'preparing', label: 'Preparing & pickup' }, { key: 'unpaid', label: 'Awaiting payment' }, { key: 'delivery', label: 'In Deliveries' }, { key: 'completed', label: 'Completed' }, { key: 'expired', label: 'Expired' }, { key: 'cancelled', label: 'Cancelled' }, { key: 'all', label: 'All orders' }];
const placedTime = value => new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(value));
const selected = ref([]);
const selectedOrders = computed(() => props.selectableOrders.filter(order => selected.value.includes(order.id)));
const bulkIds = stage => selectedOrders.value.filter(order => order.status === ({ preparing: 'received', ready: 'preparing', out_for_delivery: 'ready' })[stage]).map(order => order.id);
const canBulk = stage => bulkIds(stage).length > 0;
const allSelected = computed(() => props.selectableOrders.length > 0 && selected.value.length === props.selectableOrders.length);
const toggleAll = () => { selected.value = allSelected.value ? [] : props.selectableOrders.map(order => order.id); };
watch(() => props.selectableOrders, orders => { selected.value = selected.value.filter(id => orders.some(order => order.id === id)); });
const action = ref(null); const busy = ref(false); const page = usePage(); const detailReference = ref(null);
const detail = computed(() => props.orders.data.find(order => order.reference === detailReference.value));
usePoll(15000, { only: ['orders', 'deliveryUrl', 'selectableOrders', 'viewCounts', 'period', 'paymentDeadline', 'serverNow'] });
const statusLabel = order => order.status === 'expired' ? 'Expired' : order.payment_method !== 'cash' && order.payment_status !== 'paid' ? 'Awaiting payment' : ({ received: 'Received', preparing: 'Preparing', ready: order.method === 'pickup' ? 'Ready for pickup' : 'Ready for delivery', out_for_delivery: 'Out for delivery', completed: 'Completed', cancelled: 'Cancelled' })[order.status] || order.status;
const label = order => order.bulk ? (({ preparing: 'Prepare selected orders', ready: 'Mark selected ready', out_for_delivery: 'Dispatch selected orders' })[order.nextStatus]) : ({ preparing: 'Start preparing', ready: order.method === 'pickup' ? 'Mark ready for pickup' : 'Mark ready for delivery', out_for_delivery: 'Dispatch order' })[order.nextStatus];
const cancelTarget = ref(null); const cancelReason = ref(''); const cancelling = ref(false);
const cancelOrder = () => { cancelling.value = true; router.post(cancelTarget.value.cancelUrl, { reason: cancelReason.value }, { preserveScroll: true, onSuccess: () => { cancelTarget.value = null; cancelReason.value = ''; }, onFinish: () => { cancelling.value = false; } }); };
const blocked = order => order.status === 'expired' || (order.payment_method !== 'cash' && order.payment_status !== 'paid');
const update = () => {
    busy.value = true;
    const options = { preserveScroll: true, onSuccess: () => { action.value = null; selected.value = []; }, onFinish: () => { busy.value = false; } };
    if (action.value.bulk) router.post(props.bulkStatusUrl, { orders: bulkIds(action.value.nextStatus), status: action.value.nextStatus }, options);
    else router.patch(action.value.statusUrl, { status: action.value.nextStatus, expected_status: action.value.status }, options);
};
</script>
<template>
    <Head title="Session orders"/><Link :href="backUrl" class="text-sm text-stone-500 underline">← Open orders</Link>
    <div class="mt-5 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
        <div class="min-w-0"><h1 class="text-3xl font-semibold">{{ periodName }}</h1><p class="mt-3 text-sm leading-6 text-stone-500">{{ viewCounts?.all ?? orders.total }} orders · Ready-to-process orders appear first.</p></div>
        <div class="flex w-full flex-wrap items-center gap-3 lg:w-auto lg:shrink-0">
            <button type="button" class="inline-flex min-h-11 flex-1 items-center justify-center whitespace-nowrap rounded-full border border-stone-300 bg-white px-5 py-3 text-sm font-medium transition-colors hover:bg-stone-50 sm:flex-none" @click="router.reload({ only: ['orders', 'deliveryUrl', 'selectableOrders', 'viewCounts', 'period', 'paymentDeadline', 'serverNow'] })">Refresh orders</button>
            <Link v-if="walkInUrl && !sessionClosed" :href="walkInUrl" class="inline-flex min-h-11 items-center justify-center rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white">Create order</Link>
        </div>
    </div>
    <section v-if="period" aria-label="Session timing" class="mt-6">
        <div class="flex items-center justify-between gap-4 rounded-2xl border border-stone-200 bg-white px-5 py-4"><div><p class="text-xs font-medium text-stone-500">{{ beforeOpening ? 'Ordering opens in' : 'Ordering closes in' }}</p><p class="mt-1 text-xs text-stone-400">{{ deadlineTime(beforeOpening ? period.opensAt : period.closesAt) }} WIB</p></div><strong class="font-mono text-2xl tabular-nums text-[#504941]" role="timer" aria-live="off">{{ sessionClosed ? (period.status === 'cancelled' ? 'Cancelled' : 'Closed') : sessionTime?.label }}</strong></div>
    </section>
    <nav aria-label="Order groups" class="mt-7 flex flex-wrap gap-2 rounded-2xl border border-stone-200 bg-white p-2"><Link v-for="tab in views" :key="tab.key" :href="`${ordersUrl}?view=${tab.key}`" :aria-current="view === tab.key ? 'page' : undefined" class="inline-flex items-center gap-2 rounded-xl px-4 py-3 text-sm transition-colors" :class="view === tab.key ? 'bg-[#504941] font-medium text-white' : 'text-stone-500 hover:bg-stone-100'">{{ tab.label }}<span class="rounded-full px-2 py-0.5 text-xs" :class="view === tab.key ? 'bg-white/15' : 'bg-stone-100'">{{ viewCounts?.[tab.key] || 0 }}</span></Link></nav>
    <p v-if="focused" class="mt-4 text-sm text-stone-500">Showing the selected order. <Link :href="`${ordersUrl}?view=all`" class="underline">Show all orders</Link></p>

    <p v-if="page.props.status" role="status" class="mt-5 text-sm text-green-800">{{ page.props.status }}</p><div v-if="!action && Object.keys(page.props.errors).length" role="alert" class="mt-5 text-sm text-red-700"><p v-for="(message,key) in page.props.errors" :key="key">{{ message }}</p></div>
    <div v-if="selected.length" class="mt-6 flex flex-wrap items-center gap-3 rounded-2xl border border-stone-200 bg-white p-4"><span class="mr-auto text-sm font-medium">{{ selected.length }} selected</span><button v-if="canBulk('preparing')" class="rounded-full bg-[#504941] px-4 py-3 text-sm font-medium text-white" @click="action = { bulk: true, nextStatus: 'preparing' }">Prepare selected ({{ bulkIds('preparing').length }})</button><button v-if="canBulk('ready')" class="rounded-full bg-[#504941] px-4 py-3 text-sm font-medium text-white" @click="action = { bulk: true, nextStatus: 'ready' }">Mark selected ready ({{ bulkIds('ready').length }})</button><button v-if="canBulk('out_for_delivery')" class="rounded-full bg-[#504941] px-4 py-3 text-sm font-medium text-white" @click="action = { bulk: true, nextStatus: 'out_for_delivery' }">Dispatch selected ({{ bulkIds('out_for_delivery').length }})</button><span v-if="!canBulk('preparing') && !canBulk('ready') && !canBulk('out_for_delivery')" class="text-xs text-stone-500">Select orders at the same stage.</span><button class="px-3 py-2 text-sm underline" @click="selected = []">Clear</button></div>
    <div class="mt-6 overflow-x-auto rounded-2xl border border-stone-200 bg-white"><table class="w-full min-w-[760px] text-left text-sm"><thead class="border-b border-stone-200 bg-stone-50 text-xs text-stone-500"><tr><th class="px-4 py-4"><input type="checkbox" :checked="allSelected" :indeterminate="selected.length > 0 && !allSelected" :disabled="!selectableOrders.length" aria-label="Select all eligible orders in this session, across all pages" class="size-4 accent-stone-700" @change="toggleAll"/></th><th class="px-5 py-4">Order / customer</th><th class="px-5 py-4">Receiving</th><th class="px-5 py-4">Payment</th><th class="px-5 py-4">Progress</th><th class="px-5 py-4 text-right">Total</th><th class="px-5 py-4">Actions</th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="order in orders.data" :key="order.reference" class="hover:bg-stone-50/50"><td class="px-4 py-4"><input v-if="selectableOrders.some(eligible => eligible.id === order.id)" v-model="selected" type="checkbox" :value="order.id" :disabled="!selectableOrders.some(eligible => eligible.id === order.id)" :aria-label="`Select ${order.reference}`" class="size-4 accent-stone-700"/></td><td class="px-5 py-4"><p class="font-mono text-xs font-semibold">{{ order.reference }}</p><p class="mt-2">{{ order.customer_name }}</p><p class="mt-1 text-xs text-stone-400">{{ placedTime(order.placedAt) }} WIB</p></td><td class="px-5 py-4 capitalize">{{ order.method }}<p v-if="order.delivery?.delivery_service_name" class="mt-1 text-xs font-semibold">{{ order.delivery.delivery_service_name }}</p><p v-if="order.delivery?.delivery_starts_at" class="mt-1 text-xs text-stone-500">{{ placedTime(order.delivery.delivery_starts_at) }} WIB</p></td><td class="px-5 py-4"><p>{{ order.payment_method === 'cash' ? 'Cash' : order.payment_method === 'qris' ? 'QRIS' : 'Bank transfer' }}</p><span class="mt-2 inline-block rounded-full px-2.5 py-1 text-xs" :class="order.payment_status === 'paid' ? 'bg-green-50 text-green-800' : 'bg-amber-50 text-amber-800'">{{ order.payment_status === 'paid' ? 'Paid' : 'Unpaid' }}</span></td><td class="px-5 py-4"><span class="rounded-full bg-stone-100 px-3 py-1.5 text-xs">{{ statusLabel(order) }}</span><p v-if="order.deliveryManaged" class="mt-2 text-xs text-stone-500">{{ order.inDeliveryTrip ? 'In current delivery trip' : 'Continue in Deliveries' }}</p></td><td class="px-5 py-4 text-right font-medium whitespace-nowrap">{{ money(order.total) }}<span v-if="order.cash_received !== null" class="mt-1 block text-xs font-normal text-stone-500">Cash received {{ money(order.cash_received) }}<span class="block">Change {{ money(order.cash_change) }}</span></span></td><td class="px-5 py-4"><div class="flex items-center gap-2"><button type="button" class="rounded-full border border-stone-300 px-3 py-2 text-xs" @click="detailReference = order.reference">Details</button><Link v-if="order.method === 'delivery' && order.status === 'out_for_delivery'" :href="order.deliveryUrl" class="rounded-full border border-stone-300 px-3 py-2 text-xs whitespace-nowrap">Open in Deliveries ↗</Link><button v-if="order.cancelUrl" type="button" class="rounded-full border border-red-200 px-3 py-2 text-xs text-red-700" @click="cancelTarget = order; cancelReason = ''">Cancel</button><button v-if="order.nextStatus && order.nextStatus !== 'completed'" type="button" :disabled="blocked(order)" class="rounded-full bg-[#504941] px-3 py-2 text-xs whitespace-nowrap text-white disabled:opacity-40" @click="action = order">{{ label(order) }}</button></div></td></tr><tr v-if="!orders.data.length"><td colspan="7" class="px-5 py-12 text-center text-stone-500">{{ view === 'new' ? 'No orders need processing right now.' : 'No orders in this group.' }}</td></tr></tbody></table></div>
    <nav class="mt-6 flex justify-between text-sm"><Link v-if="orders.prev_page_url" :href="orders.prev_page_url" preserve-state class="underline">← Previous</Link><span v-else/><Link v-if="orders.next_page_url" :href="orders.next_page_url" preserve-state class="underline">Next →</Link></nav>
    <Dialog :open="Boolean(detail)" :title="detail?.reference" @close="detailReference = null"><template v-if="detail"><p class="text-sm font-semibold">{{ detail.customer_name }} · {{ detail.phone }}</p><p class="mt-2 text-sm capitalize text-stone-500">{{ detail.method }} · {{ statusLabel(detail) }}</p><div class="mt-5"><OrderProgress :order="detail"/></div><div class="mt-5 space-y-4"><div v-for="(item,index) in detail.items" :key="index"><p class="text-sm">{{ item.quantity }} × {{ item.name }} · {{ money(item.line_total) }}</p><p class="mt-1 text-xs text-stone-500">{{ item.choices.map(choice => `${choice.group}: ${choice.name}`).join(' · ') }}</p></div></div><p v-if="detail.delivery" class="mt-4 rounded-xl bg-stone-50 p-4 text-sm leading-6">Delivery: {{ detail.delivery.address_line }}</p><p class="mt-5 flex justify-between border-t border-stone-200 pt-4 text-sm font-semibold"><span>Total · {{ detail.payment_status }}</span><span>{{ money(detail.total) }}</span></p><p v-if="detail.cash_received !== null" class="mt-3 text-sm">Cash received {{ money(detail.cash_received) }} · Change {{ money(detail.cash_change) }}</p><p v-if="blocked(detail)" class="mt-4 text-xs leading-5 text-stone-500">Transfer requires verification before preparation. The seller can prepare this order once payment is verified.</p></template></Dialog>
    <Dialog :open="Boolean(action)" :title="action ? label(action) : ''" :busy="busy" @close="action = null"><p class="text-sm leading-6">{{ action?.bulk ? `Update ${bulkIds(action.nextStatus).length} selected orders?` : `Update ${action?.reference}?` }} The customer will see this progress on their order page.</p><div v-if="Object.keys(page.props.errors).length" role="alert" class="mt-4 text-sm text-red-700"><p v-for="(message,key) in page.props.errors" :key="key">{{ message }}</p></div><div class="mt-6 flex justify-end gap-3"><button type="button" :disabled="busy" class="rounded-full border border-stone-300 px-4 py-3 text-sm" @click="action = null">Back</button><button type="button" :disabled="busy" class="rounded-full bg-[#504941] px-5 py-3 text-sm text-white" @click="update">{{ busy ? 'Updating…' : 'Confirm' }}</button></div></Dialog>
<Dialog :open="Boolean(cancelTarget)" title="Cancel order" :busy="cancelling" @close="cancelTarget = null"><p class="text-sm">Cancel {{ cancelTarget?.reference }}? This order will not be prepared or delivered.</p><label class="mt-4 block text-sm">Reason<textarea v-model="cancelReason" maxlength="500" class="mt-2 w-full rounded-xl border border-stone-300 p-3"/></label><p v-for="(error,key) in page.props.errors" :key="key" class="mt-2 text-sm text-red-700" role="alert">{{ error }}</p><button type="button" :disabled="cancelling || !cancelReason.trim()" class="mt-5 rounded-full bg-red-700 px-5 py-3 text-sm text-white disabled:opacity-40" @click="cancelOrder">{{ cancelling ? 'Cancelling…' : 'Confirm cancellation' }}</button></Dialog></template>
